		name    string
		job     *Job
		wantErr bool
	}{
		{
			name: "valid job",
			job: &Job{
				Name:     "valid",
				Schedule: "0 * * * *",
				Handler:  func(_ context.Context) error { return nil },
			},
			wantErr: false,
		},
