				Name:    "test",
				Handler: func(_ context.Context) error { return nil },
			},
			wantErr: true,
		},
		{
			name: "invalid cron expression",
			job: &Job{
				Name:     "test",
				Schedule: "invalid cron",
				Handler:  func(_ context.Context) error { return nil },
